#!/usr/bin/env python3
# Generated by Claude (Opus 5.5), 2026-10-04
"""Compare Google Benchmark JSON results: baseline runs against current runs.

Usage: bench-compare.py [--noise PCT] --baseline B.json [B2.json ...] --current C.json [C2.json ...]

Prints one line per benchmark: median ns per tick before and after, the change,
and a verdict. A change is called faster/slower only when it is larger than the
noise threshold AND the two sets of samples differ significantly (Mann-Whitney
U test, p < 0.01; needs scipy, otherwise the samples must not overlap).
Per-call benchmarks are compared on their percentile counters instead of time.
"""
import argparse
import json
import re
import statistics
import sys

try:
    from scipy.stats import mannwhitneyu
except ImportError:
    mannwhitneyu = None

PERCENTILES = ["p50", "p99", "p99.9", "p99.99"]


def load(paths):
    """Return {row name: [samples]} in first-seen order, merged over all files."""
    rows = {}
    for path in paths:
        with open(path) as f:
            data = json.load(f)
        for b in data["benchmarks"]:
            if b.get("run_type", "iteration") != "iteration":
                continue
            name = b.get("run_name", b["name"])
            if "p50" in b:  # per-call benchmark: its time includes the timer
                for p in PERCENTILES:
                    rows.setdefault(f"{name} {p}", []).append(b[p])
            else:
                if b["time_unit"] != "ns":
                    sys.exit(f"{path}: {name}: expected ns, got {b['time_unit']}")
                rows.setdefault(name, []).append(b["real_time"])
    return rows


def natural(name):
    """Sort key: path before corpus before percall, numbers in numeric order."""
    family = next((i for i, f in enumerate(("/path/", "/corpus/", "/percall/")) if f in name), 3)
    parts = re.split(r"(-?\d+)", name)
    return [family] + [int(p) if re.fullmatch(r"-?\d+", p) else p for p in parts]


def differs(old, new):
    if mannwhitneyu is not None and len(old) >= 4 and len(new) >= 4:
        return mannwhitneyu(old, new, alternative="two-sided").pvalue < 0.01
    return max(old) < min(new) or max(new) < min(old)


def main():
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("--noise", type=float, default=5.0,
                    help="changes smaller than this many percent are not called (default 5)")
    ap.add_argument("--baseline", nargs="+", required=True)
    ap.add_argument("--current", nargs="+", required=True)
    args = ap.parse_args()

    old_rows, new_rows = load(args.baseline), load(args.current)
    names = sorted((n for n in new_rows if n in old_rows), key=natural)
    if not names:
        sys.exit("no benchmark appears in both result sets")

    width = max(len(n) for n in names)
    print(f"{'benchmark':<{width}}  {'old ns':>8}  {'new ns':>8}  {'change':>8}")
    called = 0
    for n in names:
        old, new = statistics.median(old_rows[n]), statistics.median(new_rows[n])
        if old == 0:
            change, verdict = ("    n/a", "") if new == 0 else ("    new", "")
        else:
            pct = 100.0 * (new - old) / old
            change = f"{pct:+7.1f}%"
            verdict = ""
            if abs(pct) > args.noise and differs(old_rows[n], new_rows[n]):
                verdict = "FASTER" if pct < 0 else "SLOWER"
                called += 1
        print(f"{n:<{width}}  {old:8.2f}  {new:8.2f}  {change:>8}  {verdict}")

    samples = len(next(iter(new_rows.values())))
    print(f"\n{called} change(s) beyond the {args.noise:g}% noise threshold "
          f"({samples} samples per benchmark, medians shown).")
    for n in old_rows:
        if n not in new_rows:
            print(f"only in baseline: {n}")
    for n in new_rows:
        if n not in old_rows:
            print(f"only in current:  {n}")


if __name__ == "__main__":
    main()
